import re

def slugify(s):
    s = s.strip().lower()
    s = re.sub(r'[^\w\s-]', '', s)
    s = re.sub(r'[\s_-]+', '-', s)
    return s.strip('-')

import re

def slugify(s):
    s = s.replace(',', '').replace('!', '')
    return re.sub(r'\s+', '-', s.strip().lower())

